#[inline]
pub fn atan(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    if x == f64::INFINITY {
        return core::f64::consts::FRAC_PI_2;
    }
    if x == f64::NEG_INFINITY {
        return -core::f64::consts::FRAC_PI_2;
    }
    if x == 0.0_f64 {
        return x;
    }
    let y = atan_positive_f64(x.abs());
    if x.is_sign_negative() {
        -y
    } else {
        y
    }
}

