#[inline]
pub fn atans(x: f16) -> f16 {
    let x32 = x as f32;
    if x32.is_nan() {
        return f16::NAN;
    }
    if x32 == f32::INFINITY {
        return core::f32::consts::FRAC_PI_2 as f16;
    }
    if x32 == f32::NEG_INFINITY {
        return -(core::f32::consts::FRAC_PI_2 as f16);
    }
    if x32 == 0.0_f32 {
        return x;
    }
    atanf(x32) as f16
}

